echo "=================================================="
echo " APPLYING PATCHES (Node.js exact-match replace, NOT sed -i, per Rule C2)"
echo "=================================================="
cat > ~/workspace/_fixscripts/apply_patches.js << 'NODEEOF'
const fs = require('fs');

function applyPatch(label, targetFile, oldFile, newFile) {
  if (!targetFile) { console.log(`⏭️  ${label} — target file not found, skipped`); return false; }
  try {
    const content = fs.readFileSync(targetFile, 'utf8');
    const oldText = fs.readFileSync(oldFile, 'utf8').replace(/\n$/, '');
    const newText = fs.readFileSync(newFile, 'utf8').replace(/\n$/, '');
    const count = content.split(oldText).length - 1;
    if (count === 0) {
      console.log(`⚠️  ${label} — pattern NOT FOUND (may already be applied or file changed). Skipped.`);
      return false;
    }
    if (count > 1) {
      console.log(`⚠️  ${label} — pattern found ${count} times (expected 1, ambiguous). Skipped for safety.`);
      return false;
    }
    const updated = content.replace(oldText, newText);
    fs.writeFileSync(targetFile, updated, 'utf8');
    console.log(`✅ ${label} — applied`);
    return true;
  } catch (e) {
    console.log(`❌ ${label} — error: ${e.message}`);
    return false;
  }
}

function blanketReplaceConfirm(label, targetFile) {
  if (!targetFile) { console.log(`⏭️  ${label} — target file not found, skipped`); return; }
  let content = fs.readFileSync(targetFile, 'utf8');
  const count = (content.match(/window\.confirm\(/g) || []).length;
  if (count === 0) { console.log(`ℹ️  ${label} — no remaining window.confirm( calls (already handled)`); return; }
  content = content.split('window.confirm(').join('await confirmAction(');
  fs.writeFileSync(targetFile, content, 'utf8');
  console.log(`✅ ${label} — replaced ${count} remaining window.confirm() call(s) with confirmAction()`);
}

const P = process.env.HOME + '/workspace/_fixscripts/patches/';
const BATCH_TSX = process.env.BATCH_TSX;
const SERIES_TSX = process.env.SERIES_TSX;
const EXAMLIST_ROUTE = process.env.EXAMLIST_ROUTE;

console.log('--- BatchManagerUltra.tsx ---');
applyPatch('Batch P1 (Modal + GlobalConfirmModal system)', BATCH_TSX, P+'batch_p1_old.txt', P+'batch_p1_new.txt');
applyPatch('Batch P3 (mount in BatchDetail)', BATCH_TSX, P+'batch_p3_old.txt', P+'batch_p3_new.txt');
applyPatch('Batch P2 (mount in main list view)', BATCH_TSX, P+'batch_p2_old.txt', P+'batch_p2_new.txt');
applyPatch('Batch P6 (ExamsTab premium redesign + Edit + Copy)', BATCH_TSX, P+'batch_p6_old.txt', P+'batch_p6_new.txt');
applyPatch('Batch P5 (doArchive/doRestoreDraft async fix)', BATCH_TSX, P+'batch_p5_old.txt', P+'batch_p5_new.txt');
