console.log('');
console.log('--- examListing.js (backend) ---');
applyPatch('Backend quick-edit (add maxAttempts)', EXAMLIST_ROUTE, P+'backend_quickedit_old.txt', P+'backend_quickedit_new.txt');
applyPatch('Backend clone-advanced (maxAttempts + testSeriesId + reverse-link)', EXAMLIST_ROUTE, P+'backend_clone_old.txt', P+'backend_clone_new.txt');
NODEEOF

BATCH_TSX="$BATCH_TSX" SERIES_TSX="$SERIES_TSX" EXAMLIST_ROUTE="$EXAMLIST_ROUTE" node ~/workspace/_fixscripts/apply_patches.js

echo ""
echo "=================================================="
echo " VERIFY — confirm no window.confirm( left anywhere in these 2 files"
echo "=================================================="
[ -n "$BATCH_TSX" ] && echo "BatchManagerUltra.tsx remaining window.confirm(: $(grep -o 'window.confirm(' "$BATCH_TSX" 2>/dev/null | wc -l)"
[ -n "$SERIES_TSX" ] && echo "TestSeriesManagerUltra.tsx remaining window.confirm(: $(grep -o 'window.confirm(' "$SERIES_TSX" 2>/dev/null | wc -l)"

echo ""
echo "=================================================="
echo " CLEANUP + COMMIT + PUSH"
echo "=================================================="
rm -rf ~/workspace/_fixscripts

git status --short
git add -A
git commit -m "Feature: premium Exams/Tests tab redesign in Batch & Test Series Manager — custom confirm modal replacing all window.confirm(), Assign confirmation, Edit modal (start/end date + attempt limit via quick-edit), Copy modal (clone-advanced with maxAttempts + proper testSeriesId + reverse-link)" || echo "ℹ️ Nothing to commit"
git push origin main

echo ""
echo "--- DONE: All applicable patches applied + pushed. Frontend (Vercel) + Backend (Render) will auto-redeploy in a couple minutes. ---"
